// end translations

// ══ setLang function ══
// NOTE (Oct 2026): the revised, non-misleading GCV/mission copy (GCV
// presented as an unconfirmed community aspiration, not fact; no more
// "Africa Pi GCV Industry Alliance" / "Vice Chair" branding) has now been
// fully translated and reviewed across all 25 languages, so the temporary
// PROTECTED_EN_IDS English-forcing guard that existed here has been removed.

// NOTE (Oct 2026): fee amounts (membership/advert/merchant) are no longer
// hardcoded inside translated sentences for any language. Every translation
// string that mentions a fee uses a placeholder token instead
// ({MEMBERSHIP_PRICE}, {ADVERT_PRICE}, {MERCHANT_PRICE}), and resolveLivePrices()
// substitutes the current price — read from window.LIVE_PRICING, which
// index.html's loadPricing() keeps in sync with the Admin Panel's
// /api/pricing endpoint — at render time, in every language. Changing a
// price in the Admin Panel now updates every language automatically; no
// translations.js edit or re-delivery is needed for a price change again.
function resolveLivePrices(str) {
  if (!str || str.indexOf('{') === -1) return str;
  const lp = (typeof LIVE_PRICING !== 'undefined' && LIVE_PRICING) ? LIVE_PRICING : {};
  const membership = lp.membership || '1';
  const advert = lp.advert || '0.01';
  const merchant = lp.merchant || '0.01';
  return str
    .replace(/\{MEMBERSHIP_PRICE\}/g, membership)
    .replace(/\{ADVERT_PRICE\}/g, advert)
    .replace(/\{MERCHANT_PRICE\}/g, merchant);
}

function setLang(l) {
  if (!translations[l]) l = 'en';
  const t = translations[l];
  document.documentElement.dir = (l === 'ar') ? 'rtl' : 'ltr';
  document.documentElement.lang = l;

  // Sync all dropdowns (.lsel/.gsel on the main DApp page, .lang-sel on landing.html)
  document.querySelectorAll('.lsel, .gsel, .lang-sel').forEach(s => { s.value = l; });

  // Update all elements
  Object.keys(t).forEach(id => {
    if (id === 'wa-msg') return; // landing.html share text — read directly from translations[], never bound to an element
    const el = document.getElementById(id);
    if (!el) return;
    let val = t[id];
    if (val === undefined) return;
    val = resolveLivePrices(val);
    // htmlIds: ids whose translated value contains markup (<strong>, etc.) and must be
    // set via innerHTML rather than textContent. Covers both the main DApp page and landing.html.
    const htmlIds = ['hero-p','alliance-box-body','gcv-explain-1','gcv-explain-2','gcv-power-tip','gcv-expert-body','unlock-prompt-body','aboutpi-tip','disclaimer-body','hero-sub','strip-p','amb-box-body','cta-sub','form-tip-txt'];
    if (htmlIds.includes(id)) {
      el.innerHTML = val;
    } else {
      el.textContent = val;
    }
  });

  // Update language buttons
  document.querySelectorAll('.lbtn').forEach(b => {
    b.classList.toggle('on', b.dataset.lang === l);
  });
}

